#[test]
fn sqlite_snapshot_tiff_erased_native_preserves_complete_custom_owner() {
    let neutral: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧾️native-owner/🔣️.json")).expect("closed neutral owner");
